import Axios from '@/server'
import type { Result } from '@/server/types'
import { DeviceManagementTypes } from './types'

/**
 * 编辑设备
 * @param deviceId 设备ID
 * @param data 编辑设备请求参数
 */
export const editDevice = (deviceId: number, data: DeviceManagementTypes.EditDeviceReq) =>
  Axios.request<Result>({
    url: `/admin/device-management/${deviceId}/edit`,
    method: 'POST',
    data
  })

/**
 * 获取设备信息
 * @param deviceId 设备ID
 */
export const getDeviceInfo = (deviceId: number) =>
  Axios.request<Result<DeviceManagementTypes.DeviceInfoRes>>({
    url: `/admin/device-management/${deviceId}/info`,
    method: 'GET'
  })

/**
 * 更新设备状态
 * @param deviceId 设备ID
 * @param data 更新状态请求参数
 */
export const updateDeviceStatus = (
  deviceId: number,
  data: DeviceManagementTypes.UpdateStatusDeviceReq
) =>
  Axios.request<Result>({
    url: `/admin/device-management/${deviceId}/update-status`,
    method: 'POST',
    data
  })

/**
 * 更改设备格子状态
 * @param gridId 格口ID
 * @param data 更新状态请求参数
 */
export const updateGridStatus = (
  gridId: number,
  data: DeviceManagementTypes.UpdateStatusDeviceGridReq
) =>
  Axios.request<Result>({
    url: `/admin/device-management/grid/${gridId}/grid-update-status`,
    method: 'POST',
    data
  })

/**
 * 获取设备列表
 * @param params 查询参数
 */
export const getDeviceList = (params?: DeviceManagementTypes.DeviceListReq) =>
  Axios.request<Result<DeviceManagementTypes.DeviceListRes>>({
    url: '/admin/device-management/list',
    method: 'GET',
    params
  })

/**
 * 设备管理类型命名空间
 * @example
 * ```typescript
 * import { deviceManagementApi } from '@/apis';
 * const params: deviceManagementApi.DeviceManagementTypes.DeviceListReq = { page: 1 };
 * ```
 */
export type { DeviceManagementTypes }
